 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+  while (pos < template.length) {
+    const open = template.indexOf("{{", pos);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(pos) });
+      break;
+    }
+    if (open > pos) tokens.push({ kind: "text", text: template.slice(pos, open) });
+
+    const raw = template.startsWith("{{{", open);
+    const delimiter = raw ? "}}}" : "}}";
+    const start = open + (raw ? 3 : 2);
+    const close = template.indexOf(delimiter, start);
+    if (close === -1) throw new Error("unterminated tag");
+
+    tokens.push(tagToken(template.slice(start, close).trim(), raw));
+    pos = close + delimiter.length;
+  }
+  return tokens;
 }
+
+function tagToken(body: string, raw: boolean): Token {
+  if (!raw) {
+    if (body === "else") return { kind: "else" };
+    if (body === "/if") return { kind: "end" };
+    if (/^#if(\s|$)/.test(body)) return { kind: "if", path: body.slice(3).trim() };
+  }
+  return { kind: "value", expr: body, raw };
+}
